const inItem = $input.first().json;
const body = inItem.body || inItem;
const submission_id = body.submission_id
  || (body.fields && body.fields.submission_id)
  || (body.record && body.record.fields && body.record.fields.submission_id)
  || (body.records && body.records[0] && body.records[0].fields && body.records[0].fields.submission_id)
  || '';
if (!submission_id) throw new Error('missing_submission_id');
return { json: { submission_id, raw: body } };

const staging = $('Fetch Staging Row').first().json;
const hubspot = $('Fetch HubSpot Company').first().json;
const customer = $('Fetch Customer Row').first().json;

const stagingRow = (staging.records || [])[0];
const customerRow = (customer.records || [])[0];

if (!stagingRow) return { json: { should_proceed: false, skip_reason: 'staging_not_found' } };
if (stagingRow.fields.status !== 'approved') return { json: { should_proceed: false, skip_reason: 'staging_not_approved', current_status: stagingRow.fields.status } };
if (!customerRow) return { json: { should_proceed: false, skip_reason: 'customer_row_not_found_check_wf0', hubspot_company_id: stagingRow.fields.hubspot_company_id } };
if (customerRow.fields['Xero ContactID']) return { json: { should_proceed: false, skip_reason: 'already_propagated', xero_contact_id: customerRow.fields['Xero ContactID'] } };

const validPaymentTerms = ['Direct debit (default)', 'Credit application', 'COD (bank transfer before dispatch)'];
const paymentTerm = stagingRow.fields.payment_term_selection;
if (!validPaymentTerms.includes(paymentTerm)) return { json: { should_proceed: false, skip_reason: 'invalid_payment_term', payment_term: paymentTerm } };

const customerGroup = (hubspot.properties && hubspot.properties.customer_group) || '일반고객';

let xeroPaymentTerm = 'NetOfDate';
if (paymentTerm === 'COD (bank transfer before dispatch)') xeroPaymentTerm = 'DueOnReceipt';

return { json: {
  should_proceed: true,
  staging_record_id: stagingRow.id,
  customer_record_id: customerRow.id,
  hubspot_company_id: stagingRow.fields.hubspot_company_id,
  customer_group: customerGroup,
  payment_term: paymentTerm,
  xero_payment_term: xeroPaymentTerm,
  shop_name: stagingRow.fields.shop_name || '',
  entity_name: stagingRow.fields.entity_name || '',
  legal_entity: stagingRow.fields.entity_name || stagingRow.fields.shop_name || '',
  abn: stagingRow.fields.abn || '',
  delivery_address: stagingRow.fields.delivery_address || '',
  form_email: stagingRow.fields.form_email || '',
  form_phone: stagingRow.fields.form_phone || '',
  account_contact_name: stagingRow.fields.account_contact_name || ''
} };

